/// <summary>
/// This is the parameter class for the tier rate calculation.
/// </summary>
[
    DataContract
]
public class METTierRateCalculationContract
{
    FromDate fromDate;
    ToDate toDate;
    TAMRebateDealId rebateDealRecId;

}

Method.Source:
/// <summary>
/// Get and sets the from date.
/// </summary>
/// <param name = "_fromDate">FromDate</param>
/// <returns>FromDate</returns>
[
    DataMemberAttribute('fromDate')
]
public FromDate parmFromDate(FromDate _fromDate = fromDate)
{
    fromDate = _fromDate;

    return fromDate;
}

/// <summary>
///  Get and sets the to date.
/// </summary>
/// <param name = "_toDate">ToDate</param>
/// <returns>ToDate</returns>
[
    DataMemberAttribute('toDate')
]
public ToDate parmToDate(ToDate _toDate = toDate)
{
    toDate = _toDate;

    return toDate;
}

/// <summary>
///  Get and sets the from rebate deal recid.
/// </summary>
/// <param name = "_rebateDealRecId">TAMRebateDealId</param>
/// <returns>TAMRebateDealId</returns>
[
    DataMemberAttribute("rebateDealRecId")
]
public TAMRebateDealId parmRebateDealRecId(TAMRebateDealId _rebateDealRecId = rebateDealRecId)
{
    rebateDealRecId = _rebateDealRecId;

    return rebateDealRecId;
}
